// "Votre commune ?" : tells the visitor whether their town is within Léa's usual zone.
// The commune list (generated by scripts/build-zone.ts) loads on first use.

import { zone, site } from '../data/site'
import { drawTrip } from './motion'

type Commune = { n: string; c: string; cp: string[]; km: number }

const fold = (s: string) =>
  s.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '')
    .replace(/\bst\b/g, 'saint').replace(/\bste\b/g, 'sainte')
    .replace(/[^a-z0-9]+/g, ' ').trim()

export function initZoneCheck(onCommune: (name: string | null) => void) {
  const form = document.querySelector<HTMLFormElement>('.zone-check')
  if (!form) return
  form.hidden = false
  const input = form.querySelector<HTMLInputElement>('input')!
  const answer = form.querySelector<HTMLElement>('.zone-answer')!
  const datalist = form.querySelector<HTMLDataListElement>('datalist')!
  const map = document.querySelector<SVGSVGElement>('.zone-map')
  let communes: Commune[] | null = null

  async function load() {
    if (communes) return communes
    communes = (await import('../generated/communes.json')).default as Commune[]
    datalist.append(...communes.filter((c) => c.km <= zone.radiusKm + 15).map((c) => new Option(c.n)))
    return communes
  }

  function find(list: Commune[], query: string): Commune[] {
    const q = fold(query)
    if (!q) return []
    if (/^\d{5}$/.test(q)) return list.filter((c) => c.cp.includes(q))
    // Same name in two départements, or "Cadillac" for Cadillac-sur-Garonne: the nearest wins
    const exact = list.filter((c) => fold(c.n) === q)
    const matches = exact.length ? exact : list.filter((c) => fold(c.n).startsWith(q))
    return matches.sort((a, b) => a.km - b.km).slice(0, 1)
  }

  function highlight(found: Commune[]) {
    if (!map) return
    map.querySelectorAll('.hit, .hit-label').forEach((el) => el.classList.remove('hit', 'hit-label'))
    map.querySelector('.hit-name')?.remove()
    for (const c of found) map.querySelector(`circle[data-c="${c.c}"]`)?.classList.add('hit')
    if (found.length !== 1) return
    // A town already named on the map gets its label in bold; others get a new one
    const named = map.querySelector<SVGTextElement>(`text[data-c="${found[0].c}"]`)
    if (named) return named.classList.add('hit-label')
    const dot = map.querySelector<SVGCircleElement>(`circle[data-c="${found[0].c}"]`)
    if (!dot) return
    const label = document.createElementNS('http://www.w3.org/2000/svg', 'text')
    label.setAttribute('class', 'hit-label hit-name')
    label.setAttribute('x', String(Number(dot.getAttribute('cx')) + 9))
    label.setAttribute('y', String(Number(dot.getAttribute('cy')) - 8))
    label.textContent = found[0].n
    map.querySelector('.labels')?.append(label)
  }

  const tel = `<a href="tel:${site.phoneHref}">appelez-moi</a>`
  // After a yes: both ways to book, right there. contact.ts fills the SMS with the commune.
  const book = `<a href="tel:${site.phoneHref}">Appelez-moi</a> ou <a data-sms href="sms:${site.phoneHref}">envoyez un SMS</a>.`
  const further = `Ça reste possible : ${tel}, on en parle.`

  async function check() {
    const query = input.value.trim()
    if (!query) {
      answer.textContent = 'Écrivez le nom de votre commune ou son code postal.'
      return
    }
    const found = find(await load(), query)
    highlight(found)
    drawTrip(map, found.length === 1 ? found[0].c : null)
    if (found.length === 0) {
      answer.innerHTML = `Je ne trouve pas « ${query.replace(/[<&]/g, '')} » autour du Sud-Gironde. Vérifiez l’orthographe, ou ${tel}.`
      onCommune(null)
      return
    }
    if (found.length > 1) {
      // A postcode covers several communes
      const kms = found.map((c) => c.km)
      const near = Math.min(...kms), far = Math.max(...kms)
      const cp = query.replace(/\D/g, '')
      if (far <= zone.radiusKm) {
        answer.innerHTML = `Oui, je me déplace dans tout le ${cp}, à moins de ${far}&nbsp;km de ${zone.base}. ${book}`
      } else if (near > zone.radiusKm) {
        answer.innerHTML = `Le ${cp} est à ${near}&nbsp;km ou plus de ${zone.base}, au-delà de ma zone habituelle. ${further}`
      } else {
        answer.innerHTML = `Une partie du ${cp} est dans ma zone. Écrivez le nom de votre commune pour vérifier, ou ${tel}.`
      }
      onCommune(null)
      return
    }
    const c = found[0]
    if (c.c === zone.code) {
      answer.innerHTML = `Oui, je suis basée à ${zone.base}. ${book}`
    } else if (c.km <= zone.radiusKm) {
      answer.innerHTML = `Oui, je me déplace à ${c.n}, à environ ${c.km}&nbsp;km de ${zone.base}. ${book}`
    } else {
      answer.innerHTML = `${c.n} est à environ ${c.km}&nbsp;km de ${zone.base}, au-delà de ma zone habituelle. ${further}`
    }
    // Last, so the SMS link just written gets the commune too
    onCommune(c.n)
  }

  input.addEventListener('focus', () => void load(), { once: true })
  form.addEventListener('submit', (e) => {
    e.preventDefault()
    void check()
  })
  // Picking a suggestion from the list answers straight away
  input.addEventListener('input', (e) => {
    if ((e as InputEvent).inputType === 'insertReplacementText' || (e as InputEvent).inputType === undefined) void check()
  })
}
